
// Import ---------------------------------------

import CustomerDetails from './home/CustomerDetails'
import RepairDetails from './home/RepairDetails'
import CourtesyPhone from './home/CourtesyPhone'
import Cost from './home/Cost'
import FormButtons from './home/Buttons'

import { supabase } from './include/supabase'

import { useNavigate } from "react-router-dom";
import { useState } from 'react'

// Component ------------------------------------

function Home( { account } ) {

    // States -------------------------

    const [ bond, setBond ] = useState(0);
    const [ customerType, setCustomerType ] = useState("customer");
    const [ warrenty, setWarrenty ] = useState(false);

    // Data ---------------------------

    // Functions/Methods --------------

    const navigate = useNavigate();

    const uploadImage = file => {
        try {
            const { error } = supabase.storage.from('images').upload(file.name, file, {cacheControl: '3600', upsert: true});
            if (error) throw error;
            const { data: link } = supabase.storage.from("images").getPublicUrl(file.name);
            return link.publicUrl;
        } catch (error) {
            console.error('Error uploading file:', error);
            alert('File upload failed.');
            return;
        }
    }

    const onSubmit = async(event) => {
        // Prevent autosubmit behavior
        event.preventDefault();

        // Get all values at once
        const form_data = new FormData(event.target);
        let form_values = Object.fromEntries(form_data.entries());

        // Manage image upload
        const image = event.target.image.files[0];
        if (image) {
            form_values.image = uploadImage(image);
        } else {
            form_values.image = null;
        }

        console.log(form_values);

        try {
            const { error } = await supabase.from('repair_bookings').insert([form_values]);
            if (error) throw error;
            event.target.reset();
        } catch (error) {
            console.error('Error adding booking:', error);
        }

        navigate("/bookings");
    }

    // Return UI ----------------------

    return (
        <>
        <form className="row" style={{ backgroundColor: '#edbb99', minHeight: '80vh' }} onSubmit={ onSubmit }>

        {/* Customer Details */}
        <div className="col-12 col-lg-4 p-4 m-0" style={{ minHeight: '70vh', backgroundColor: '#fcf3df' }}>
        <CustomerDetails account={ account } setCustomerType={ setCustomerType } />
        </div>

        {/* Repair Details */}
        <div className="col-12 col-lg-4 p-4 m-0" style={{ minHeight: '70vh', backgroundColor: '#d5f5e3' }}>
        <RepairDetails setWarrenty={ setWarrenty } />
        </div>

        {/* Courtesy Phone and Cost */}
        <div className="col-12 col-lg-4 p-0 m-0" style={{ minHeight: '70vh' }}>

            {/* Courtesy Phone */}
            <div className="col-12 p-4 m-0" style={{ backgroundColor: '#4884b6' }}>
            <CourtesyPhone setBond={ setBond } />
            </div>

            {/* Cost */}
            <div className="col-12 p-4 m-0" style={{ backgroundColor: '#edbb99' }}>
            <Cost bond={ bond } warrenty={ warrenty } customerType={ customerType } />
            </div>

        </div>

        {/* Buttons */}
        <div className="col-12 p-4 m-0" style={{ minHeight: '10vh', backgroundColor: '#edbb99' }}>
        <FormButtons/>
        </div>

        </form>
        </>
    );
};

// Export Component -----------------------------

export default Home;

