
// Import ---------------------------------------

import { useState } from 'react';

// Component ------------------------------------

function Search( { bookings } ) {

    // States -------------------------

    const [ query, setQuery ] = useState('');
    const [ filter, setFilter ] = useState('Filter By...');
    const [ order, setOrder ] = useState('Order By...');

    // Data ---------------------------


    const filter_options = {
        'Filter By...': () => true,
        'Customer Type Only': (booking) => (booking.customer_type === 'Customer'),
        'Business Type Only': (booking) => (booking.customer_type === 'Business'),
        'Has Warrenty': (booking) => (booking.warrenty === "warrenty"),
        'Has No Warrenty': (booking) => (booking.warrenty !== "warrenty"),
        'Has Image Attached': (booking) => (booking.image !== null)
    };

    const order_options = {
        'Order By...': () => true,
        'Surname (A-Z)': (a, b) => (a.lname.localeCompare(b.lname)),
        'Surname (Z-A)': (a, b) => (b.lname.localeCompare(a.lname)),
        'Repair Date (Soonest)': (a, b) => (a.repair_date > b.repair_date),
        'Repair Date (Latest)': (a, b) => (b.repair_date > a.repair_date)
    };

    // Functions/Methods --------------

    // Return UI ----------------------

    return (
        <>
            <div className='row align-items-center'>
                <div className='col-8'>
                    <input className="form-control m-3" type="text" name="search" placeholder="Search"
                        onChange={ (e) => setQuery(e.target.value) }
                    />
                </div>
                <div className="col-2">
                    <select className="form-select" name="filter by"
                        onChange={ (e) => setFilter(e.target.value) }>
                        { Object.keys(filter_options).map( item => (<option key={item} value={item}>{item}</option>) ) }
                    </select>
                </div>
                <div className="col-2">
                    <select className="form-select" name="order by"
                        onChange={ (e) => setOrder(e.target.value) }>
                        { Object.keys(order_options).map( item => (<option key={item} value={item}>{item}</option>) ) }
                    </select>
                </div>
            </div>

            <div>
            {
                /* Loop through all values in the booking to find a match for user query */
                bookings.filter( booking => 
                    Object.values(booking).some( item => {
                        return (String(item).toLowerCase().includes(query.toLowerCase()))
                    })
                /* Loop through all values in the booking to find a match for user filter */
                ).filter( filter_options[filter]
                /* Sort by the users preferance */
                ).sort( order_options[order]
                /* Loop through all remaining bookings and insert them into the HTML */
                ).map( booking => { return (
                    <div key={booking.id} className='row p-2 m-2' style={{backgroundColor: '#fcf3df'}}>
                    <h4>{booking.title} {booking.fname} {booking.lname}</h4>
                    <div className="col-12 col-lg-4 p-4 m-0">
                        <h5><b>Customer Type:</b> {booking.customer_type}</h5>
                        <br/>
                        <p><b>Adress:</b></p>
                        <p>{booking.street}<br/>
                        {booking.suburb}<br/>
                        {booking.city}<br/>
                        {booking.postcode}</p>
                        <p><b>Phone:</b> {booking.phone}</p>
                        <p><b>Email:</b> {booking.email}</p>
                    </div>
                    <div className="col-12 col-lg-4 p-4 m-0">
                        <p><b>Purchase Date:</b> {booking.purchase_date}</p>
                        <p><b>Repair Date:</b> {booking.repair_date}</p>
                        <p><b>Under Warrenty:</b> {booking.warrenty === "warrenty" ? "Yes" : "No"}</p>
                        <p><b>IMEI Number:</b> {booking.imei}</p>
                        <p><b>Make:</b> {booking.make}</p>
                        <p><b>Model Number:</b> {booking.model_number ? booking.model_number : "Not provided"}</p>
                        <p><b>Fault:</b> {booking.fault}</p>
                        <p><b>Description:</b> {booking.description ? booking.description : "No description provided"}</p>
                        <p><b>Image:</b> {booking.image ? 
                            <>
                                <span className="text-decoration-underline text-dark" data-bs-toggle="modal" data-bs-target={'#image'+booking.id}> View attatched image </span>
                                <div className="modal fade" id={'image'+booking.id} tabIndex="-1" role="dialog" aria-labelledby="exampleModalLabel" aria-hidden="true" key={booking.id}>
                                    <div className="modal-dialog" role="document">
                                        <div className="modal-content">
                                            <img src={booking.image} alt={"Image uploaded by " + booking.fname + ", Booking ID " + booking.id}/> 
                                        </div>
                                    </div>
                                </div>
                            </> : "No image provided"
                        }</p>
                    </div>
                    <div className="col-12 col-lg-4 p-4 m-0">
                        <p><b>Courtesy Phone ID:</b> {booking.courtesy_phone !== "none" ? booking.courtesy_phone : "None selected"}</p>
                        <p><b>Courtesy Charger ID:</b> {booking.courtesy_charger !== "none" ? booking.courtesy_charger : "None selected"}</p>
                        <br/>
                        <p><b>Bond:</b> {booking.bond}</p>
                        <p><b>Servive Fee:</b> {booking.service_fee}</p>
                        <p><b>Total:</b> {booking.total}</p>
                        <p><b>GST:</b> {booking.gst}</p>
                        <p><b>Total w/ GST:</b> {booking.total_w_gst}</p>
                    </div>
                    </div>
                )})
            }
            </div>
        </>
    );
};

// Export Component -----------------------------

export default Search;

