
// Import ---------------------------------------

import { useState } from "react";

// Component ------------------------------------

function RepairDetails( { setWarrenty } ) {

    // States -------------------------

    const [ imagePreview, updateImagePreview ] = useState(null);

    // Data ---------------------------

    // Functions/Methods --------------

    const checkWarrenty = (e) => {
        let purchaseDate = new Date(e.target.value);
        let currentDate = new Date();

        let timeDifference = currentDate - purchaseDate;
        let monthsDifference = Math.ceil(timeDifference / (1000*60*60*24*30));

        document.getElementById('warrenty').disabled =  monthsDifference > 24;
        if (monthsDifference > 24) { 
            document.getElementById('warrenty').checked = false;
            setWarrenty( false );
        }
    };

    // Return UI ----------------------

    return (
        <>
        <h2>Repair Details</h2>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Purchase Date</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="date" name="purchase_date" className="form-control" 
                max={ new Date(Date.now()).toISOString().split("T")[0] }
                onChange={ checkWarrenty }
                required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Repair Date</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="date" name="repair_date" className="form-control" 
                min={ new Date(Date.now()).toISOString().split("T")[0] }
                required/>
            </div>
        </div>

        <div className="row p-1">
            <fieldset className="border border-primary col-12">
            <legend className="col-11 float-none w-auto">Under Warrenty</legend>
            <div className="form-check">
            <input className="form-check-input" type="checkbox" id="warrenty" name="warrenty" disabled={true} value="warrenty"
                onChange={ event => setWarrenty( event.target.checked ) }/>
            <label className="form-check-label">
            Warrenty
            </label>
            </div>
            </fieldset>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">IMEI Number</label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="imei" className="form-control"
                pattern="^[0-9]{15}" title="The IMEI number should be exactly 15 digits"
                onInput={ (e) => e.target.value = e.target.value.replace("/[0-9]/g", '') }
                required/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Make</label>
            </div>
            <div className="col-12 col-lg-8">
                <select className="form-select" name="make">
                    <option value="Apple" defaultValue>Apple</option>
                    <option value="LG">LG</option>
                    <option value="Motorola">Motorola</option>
                    <option value="Nokia">Nokia</option>
                    <option value="Samsung">Samsung</option>
                    <option value="Sony">Sony</option>
                    <option value="Other">Other</option>
                </select>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Model Number <i>(Optional)</i></label>
            </div>
            <div className="col-12 col-lg-8">
                <input type="text" name="model_number" className="form-control"/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Fault</label>
            </div>
            <div className="col-12 col-lg-8">
                <select className="form-select" name="fault">
                    <option value="Battery" defaultValue>Battery</option>
                    <option value="Charging">Charging</option>
                    <option value="Screen">Screen</option>
                    <option value="SD-storage">SD-storage</option>
                    <option value="Software">Software</option>
                    <option value="Other">Other</option>
                </select>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Description</label>
            </div>
            <div className="col-12 col-lg-8">
                <textarea type="text" name="description" className="form-control"/>
            </div>
        </div>

        <div className="row p-1">
            <div className="col-12 col-lg-4">
                <label className="col-form-label">Image <i>(Optional)</i></label>
            </div>
            <div className="col-12 col-lg-8">
                <div className="input-group mb-3">
                    <input type="file" name="image" className="form-control"
                        onChange={ event => {
                            const file = event.target.files[0];
                            if (file) {
                                updateImagePreview(URL.createObjectURL(file));
                            } else { updateImagePreview(null) }
                        } }/>
                </div>
                { imagePreview ? 
                    <>
                        <p className="text-decoration-underline text-dark" data-bs-toggle="modal" data-bs-target='#imagePreview'> View image </p>
                        <div className="modal fade" id='imagePreview' tabIndex="-1" role="dialog" aria-labelledby="exampleModalLabel" aria-hidden="true">
                            <div className="modal-dialog" role="document">
                                <div className="modal-content">
                                    <img src={imagePreview} alt="Upload preview"/> 
                                </div>
                            </div>
                        </div>
                    </>
                    : <div/>}
            </div>
        </div>

        </>
    );
};

// Export Component -----------------------------

export default RepairDetails;

